    const int TILE_SIZE = 32;

    // Shared memory for tiles of A and B
    __shared__ float sA[TILE_SIZE][TILE_SIZE];
    __shared__ float sB[TILE_SIZE][TILE_SIZE];

    // Thread's global row and column index
    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    // Iterate over tiles
    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; ++tile) {
        // Load tiles from global memory to shared memory
        int a_row = row;
        int a_col = tile * TILE_SIZE + threadIdx.x;
        if (a_row < N && a_col < N) {
            sA[threadIdx.y][threadIdx.x] = A[a_row * N + a_col];
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if outside matrix bounds
        }

        int b_row = tile * TILE_SIZE + threadIdx.y;
        int b_col = col;
        if (b_row < N && b_col < N) {
            sB[threadIdx.y][threadIdx.x] = B[b_row * N + b_col];
        } else {
            sB[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if outside matrix bounds
        }

        __syncthreads(); // Synchronize threads to ensure tiles are loaded

        // Perform dot product using shared memory
        for (int k = 0; k < TILE_SIZE; ++k) {
            sum += sA[threadIdx.y][k] * sB[k][threadIdx.x];
